#include "PluginEditor.h"
namespace{auto bg=juce::Colour(0xff0b0e12);auto panel=juce::Colour(0xff15191f);auto orange=juce::Colour(0xffff7a12);auto text=juce::Colour(0xffeee9df);auto dim=juce::Colour(0xffaaa395);} 
AECompressorEditor::LAF::LAF(){setColour(juce::Slider::textBoxTextColourId,text);setColour(juce::Slider::textBoxBackgroundColourId,juce::Colours::transparentBlack);setColour(juce::Slider::textBoxOutlineColourId,juce::Colours::transparentBlack);}
void AECompressorEditor::LAF::drawRotarySlider(juce::Graphics&g,int x,int y,int w,int h,float pos,float st,float en,juce::Slider&){auto r=juce::Rectangle<float>((float)x,(float)y,(float)w,(float)h).reduced(9);auto c=r.getCentre();float rad=std::min(r.getWidth(),r.getHeight())*.5f,ang=st+pos*(en-st);g.setColour(juce::Colour(0xff07090c));g.fillEllipse(r.expanded(4));g.setGradientFill(juce::ColourGradient(juce::Colour(0xff4b4f55),c.x,r.getY(),juce::Colour(0xff15181d),c.x,r.getBottom(),false));g.fillEllipse(r);g.setColour(orange);g.drawArc(r.expanded(3),st,ang,3);juce::Path q;q.addRoundedRectangle(-2,-rad*.75f,4,rad*.42f,2);g.setColour(text);g.fillPath(q,juce::AffineTransform::rotation(ang).translated(c.x,c.y));}
AECompressorEditor::AECompressorEditor(AECompressorProcessor&x):AudioProcessorEditor(x),p(x){setLookAndFeel(&laf);setSize(1080,700);knob(input,il,"INPUT"," dB");knob(threshold,tl,"THRESHOLD"," dB");knob(output,ol,"OUTPUT"," dB");knob(mix,ml,"MIX"," %");knob(ratio,rl,"RATIO",":1");knob(attack,al,"ATTACK"," ms");knob(release,rel,"RELEASE"," ms");knob(makeup,makl,"MAKE-UP"," dB");knob(bass,bl,"BASS IGNORE"," Hz");for(auto*b:{&soft,&medium,&hard})addAndMakeVisible(*b);auto sk=[this](int k){auto*q=p.apvts.getParameter("knee");q->setValueNotifyingHost(q->convertTo0to1((float)k));};soft.onClick=[sk]{sk(0);};medium.onClick=[sk]{sk(1);};hard.onClick=[sk]{sk(2);};addAndMakeVisible(autoGain);addAndMakeVisible(bypass);std::array<juce::String,8>n{"VOCAL","KICK","BASS","SNARE","DRUM BUS","MIX BUS","MASTER","PARALLEL"};for(int i=0;i<8;++i){presets[(size_t)i].setButtonText(n[(size_t)i]);addAndMakeVisible(presets[(size_t)i]);presets[(size_t)i].onClick=[this,i]{p.applyPreset(i);};}
a1=std::make_unique<SA>(p.apvts,"input",input);a2=std::make_unique<SA>(p.apvts,"threshold",threshold);a3=std::make_unique<SA>(p.apvts,"output",output);a4=std::make_unique<SA>(p.apvts,"mix",mix);a5=std::make_unique<SA>(p.apvts,"ratio",ratio);a6=std::make_unique<SA>(p.apvts,"attack",attack);a7=std::make_unique<SA>(p.apvts,"release",release);a8=std::make_unique<SA>(p.apvts,"makeup",makeup);a9=std::make_unique<SA>(p.apvts,"bassIgnore",bass);b1=std::make_unique<BA>(p.apvts,"autoGain",autoGain);b2=std::make_unique<BA>(p.apvts,"bypass",bypass);startTimerHz(30);}
void AECompressorEditor::knob(juce::Slider&s,juce::Label&l,const juce::String&n,const juce::String&u){addAndMakeVisible(s);addAndMakeVisible(l);s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);s.setTextBoxStyle(juce::Slider::TextBoxBelow,false,90,22);s.setTextValueSuffix(u);l.setText(n,juce::dontSendNotification);l.setJustificationType(juce::Justification::centred);l.setColour(juce::Label::textColourId,text);l.setFont(juce::FontOptions(13,juce::Font::bold));}
void AECompressorEditor::timerCallback(){gr+=.35f*(p.reductionDb()-gr);in+=.3f*(p.inputDb()-in);out+=.3f*(p.outputDb()-out);int k=(int)p.apvts.getRawParameterValue("knee")->load();soft.setToggleState(k==0,juce::dontSendNotification);medium.setToggleState(k==1,juce::dontSendNotification);hard.setToggleState(k==2,juce::dontSendNotification);int pr=(int)p.apvts.getRawParameterValue("preset")->load();for(int i=0;i<8;++i)presets[(size_t)i].setToggleState(i==pr,juce::dontSendNotification);repaint();}
void AECompressorEditor::meter(juce::Graphics&g,juce::Rectangle<float>a,float db,bool red,const juce::String&t){g.setColour(dim);g.setFont(juce::FontOptions(12,juce::Font::bold));g.drawText(t,a.removeFromTop(22),juce::Justification::centred);auto bar=a.reduced(22,8);g.setColour(juce::Colour(0xff07090c));g.fillRoundedRectangle(bar,4);float n=red?juce::jlimit(0.0f,1.0f,db/30.0f):juce::jlimit(0.0f,1.0f,(db+60)/60);auto f=bar;f.removeFromTop(bar.getHeight()*(1-n));g.setGradientFill(juce::ColourGradient(red?orange:juce::Colour(0xffffff33),f.getX(),f.getY(),red?juce::Colour(0xffff3a00):juce::Colour(0xff44d933),f.getX(),f.getBottom(),false));g.fillRoundedRectangle(f,3);g.setColour(orange);g.drawText(red?"-"+juce::String(db,1)+" dB":juce::String(db,1)+" dB",a.removeFromBottom(24),juce::Justification::centred);}
void AECompressorEditor::paint(juce::Graphics&g){g.fillAll(bg);auto r=getLocalBounds().toFloat().reduced(8);auto head=r.removeFromTop(58),foot=r.removeFromBottom(128),low=r.removeFromBottom(168);g.setColour(panel);g.fillRoundedRectangle(head,8);g.fillRoundedRectangle(r,8);g.fillRoundedRectangle(low,8);g.fillRoundedRectangle(foot,8);g.setColour(orange);g.setFont(juce::FontOptions(28,juce::Font::bold));g.drawText("AE",head.removeFromLeft(75),juce::Justification::centred);g.setColour(text);g.setFont(juce::FontOptions(24,juce::Font::bold));g.drawText("AE COMPRESSOR",head,juce::Justification::centred);auto main=r.reduced(8);main.removeFromLeft(165);main.removeFromRight(165);meter(g,main.removeFromLeft(110).reduced(8,16),gr,true,"GAIN REDUCTION");meter(g,main.removeFromRight(110).reduced(8,16),out,false,"OUTPUT LEVEL");g.setColour(orange);g.setFont(juce::FontOptions(15,juce::Font::bold));g.drawText("PRESETS",foot.removeFromTop(24),juce::Justification::centred);g.setColour(dim);g.setFont(juce::FontOptions(12));g.drawFittedText("BASS IGNORE: low frequencies are ignored only by the detector. The bass is not removed from the sound.",low.removeFromRight(250).reduced(18).toNearestInt(),juce::Justification::centredLeft,5);}
void AECompressorEditor::resized(){auto r=getLocalBounds().reduced(8);r.removeFromTop(66);auto foot=r.removeFromBottom(128),low=r.removeFromBottom(168),main=r.reduced(8);auto L=main.removeFromLeft(165).reduced(18),R=main.removeFromRight(165).reduced(18),C=main;C.removeFromLeft(110);C.removeFromRight(110);auto place=[](juce::Rectangle<int>a,juce::Label&l,juce::Slider&s){l.setBounds(a.removeFromTop(20));s.setBounds(a);};place(L.removeFromTop(170),il,input);L.removeFromTop(15);place(L.removeFromTop(145),bl,bass);place(R.removeFromTop(170),ol,output);R.removeFromTop(15);place(R.removeFromTop(145),ml,mix);autoGain.setBounds(R.removeFromTop(30));C.removeFromTop(42);place(C.removeFromTop(280).reduced(30,0),tl,threshold);auto kr=C.removeFromTop(36).withSizeKeepingCentre(330,34);soft.setBounds(kr.removeFromLeft(105));kr.removeFromLeft(8);medium.setBounds(kr.removeFromLeft(105));kr.removeFromLeft(8);hard.setBounds(kr.removeFromLeft(105));low.removeFromRight(250);auto ks=low.reduced(12);int w=ks.getWidth()/4;place(ks.removeFromLeft(w),rl,ratio);place(ks.removeFromLeft(w),al,attack);place(ks.removeFromLeft(w),rel,release);place(ks,makl,makeup);foot.removeFromTop(28);auto pa=foot.reduced(12,4);auto ba=pa.removeFromRight(135);int pw=pa.getWidth()/8;for(auto&b:presets)b.setBounds(pa.removeFromLeft(pw).reduced(3,2));bypass.setBounds(ba.reduced(6,18));}
